  ('10000000-0000-0000-0000-000000000004', '된장찌개', '두부와 애호박을 넣은 기본 된장찌개', 2),
  ('10000000-0000-0000-0000-000000000005', '계란볶음밥', '냉장고 재료로 빠르게 만드는 한 그릇', 1),
  ('10000000-0000-0000-0000-000000000006', '제육볶음', '매콤한 양념으로 볶아내는 돼지고기 요리', 2),
  ('10000000-0000-0000-0000-000000000007', '오일파스타', '마늘 향을 살린 간단한 오일 파스타', 1),
  ('10000000-0000-0000-0000-000000000008', '닭갈비', '닭고기와 채소를 매콤하게 볶는 한 끼', 2)
ON CONFLICT (id) DO NOTHING;

