INSERT INTO recipe_steps (id, recipe_id, step_index, instruction, timer_seconds, caution_note) VALUES
  ('30000000-0000-0000-0000-000000000301', '10000000-0000-0000-0000-000000000003', 0, '두부의 물기를 닦고 먹기 좋은 크기로 써세요.', 300, NULL),
  ('30000000-0000-0000-0000-000000000302', '10000000-0000-0000-0000-000000000003', 1, '팬에 두부를 올려 앞뒤로 노릇하게 구우세요.', 360, '기름이 튈 수 있어요'),
  ('30000000-0000-0000-0000-000000000303', '10000000-0000-0000-0000-000000000003', 2, '양념과 물을 넣고 중약불에서 졸이세요.', 300, '양념이 타지 않게 불을 줄이세요'),
  ('30000000-0000-0000-0000-000000000304', '10000000-0000-0000-0000-000000000003', 3, '대파를 올리고 불을 끄세요.', NULL, NULL),

  ('30000000-0000-0000-0000-000000000401', '10000000-0000-0000-0000-000000000004', 0, '애호박, 양파, 두부를 한입 크기로 써세요.', 300, NULL),
  ('30000000-0000-0000-0000-000000000402', '10000000-0000-0000-0000-000000000004', 1, '냄비에 물을 끓이고 된장을 풀어주세요.', 240, NULL),
  ('30000000-0000-0000-0000-000000000403', '10000000-0000-0000-0000-000000000004', 2, '채소와 두부를 넣고 끓이세요.', 480, '국물이 넘치지 않게 중불을 유지하세요'),
  ('30000000-0000-0000-0000-000000000404', '10000000-0000-0000-0000-000000000004', 3, '간을 보고 불을 끄세요.', NULL, NULL),

  ('30000000-0000-0000-0000-000000000501', '10000000-0000-0000-0000-000000000005', 0, '대파를 잘게 썰고 계란을 풀어주세요.', 180, NULL),
  ('30000000-0000-0000-0000-000000000502', '10000000-0000-0000-0000-000000000005', 1, '달군 팬에 계란을 넣어 부드럽게 익히세요.', 120, NULL),
  ('30000000-0000-0000-0000-000000000503', '10000000-0000-0000-0000-000000000005', 2, '대파와 밥을 넣고 고루 볶으세요.', 240, '센 불에서는 밥이 탈 수 있어요'),
  ('30000000-0000-0000-0000-000000000504', '10000000-0000-0000-0000-000000000005', 3, '간장을 가장자리에 두르고 한 번 더 볶으세요.', 60, NULL),

  ('30000000-0000-0000-0000-000000000601', '10000000-0000-0000-0000-000000000006', 0, '돼지고기에 고추장과 간장을 넣어 버무리세요.', 300, NULL),
  ('30000000-0000-0000-0000-000000000602', '10000000-0000-0000-0000-000000000006', 1, '달군 팬에 양념한 고기를 넣고 볶으세요.', 420, '고기가 완전히 익었는지 확인하세요'),
  ('30000000-0000-0000-0000-000000000603', '10000000-0000-0000-0000-000000000006', 2, '양파와 대파를 넣고 함께 볶으세요.', 240, NULL),
  ('30000000-0000-0000-0000-000000000604', '10000000-0000-0000-0000-000000000006', 3, '간을 보고 불을 끄세요.', NULL, NULL),

  ('30000000-0000-0000-0000-000000000701', '10000000-0000-0000-0000-000000000007', 0, '소금을 넣은 물에 스파게티면을 삶으세요.', 480, '끓는 물에 데이지 않게 주의하세요'),
  ('30000000-0000-0000-0000-000000000702', '10000000-0000-0000-0000-000000000007', 1, '팬에 올리브유와 마늘을 넣고 약불로 익히세요.', 240, '마늘을 태우지 마세요'),
  ('30000000-0000-0000-0000-000000000703', '10000000-0000-0000-0000-000000000007', 2, '삶은 면과 면수 반 컵을 넣고 섞으세요.', 180, NULL),
  ('30000000-0000-0000-0000-000000000704', '10000000-0000-0000-0000-000000000007', 3, '소금으로 간하고 불을 끄세요.', NULL, NULL),

  ('30000000-0000-0000-0000-000000000801', '10000000-0000-0000-0000-000000000008', 0, '닭고기에 고추장을 넣고 고루 버무리세요.', 300, NULL),
  ('30000000-0000-0000-0000-000000000802', '10000000-0000-0000-0000-000000000008', 1, '달군 팬에 닭고기를 넣고 볶으세요.', 480, '닭고기 속까지 완전히 익혀야 해요'),
  ('30000000-0000-0000-0000-000000000803', '10000000-0000-0000-0000-000000000008', 2, '양배추와 고구마를 넣고 함께 볶으세요.', 420, '팬이 마르면 물을 조금 추가하세요'),
  ('30000000-0000-0000-0000-000000000804', '10000000-0000-0000-0000-000000000008', 3, '대파를 넣고 한 번 더 볶은 뒤 불을 끄세요.', 120, NULL)
ON CONFLICT (id) DO NOTHING;
